API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(WAF_Rate_Limiting_Engine, "WAF & Rate Limiting Engine", "NGINX/Kong", "Protects against web attacks and enforces traffic limits.")
    Component(JWTOAuth2_Filters, "JWT/OAuth2 Filters", "NGINX/Kong Plugin / OAuth2", "Validates incoming tokens and handles authentication filters.")
    Component(Routing_Engine, "Routing Engine", "NGINX/Kong Routing", "Routes external HTTPS/TLS 1.3 requests to internal microservices via mTLS.")
}

Rel(WAF_Rate_Limiting_Engine, JWTOAuth2_Filters, "Inspects and passes requests")
Rel(JWTOAuth2_Filters, Routing_Engine, "Authorizes and forwards requests")
@enduml

Identity Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(identity_service, "Identity Service") {
    Component(Authentication_Engine, "Authentication Engine", "Keycloak", "Manages authentication, identity federation, and credential verification.")
    Component(Authorization_Token_Management_Module, "Authorization & Token Management Module", "Keycloak, Redis & Infinispan", "Handles authorization, OAuth2/OIDC token issuance, and sub-millisecond token validation.")
    Component(User_Federation_Provider, "User Federation Provider", "Keycloak", "Interoperates for staff credentials over LDAPS with enterprise LDAP directories.")
}

Rel(Authentication_Engine, Authorization_Token_Management_Module, "Passes authenticated identity context for token generation")
Rel(User_Federation_Provider, Authentication_Engine, "Validates staff credentials against external directories")
@enduml

HL7 FHIR Integration Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("HL7 FHIR Integration Engine", "HL7 FHIR Integration Engine") {
    Component("FHIR Route Orchestrator", "FHIR Route Orchestrator", "Apache Camel", "Orchestrates routes and message flows for clinical data within the integration engine.")
    Component("Data Transformation Processor", "Data Transformation Processor", "HAPI FHIR", "Parses and transforms clinical data structures using HAPI FHIR libraries.")
    Component("Validation & Compliance Interceptor", "Validation & Compliance Interceptor", "Java / Apache Camel Interceptor", "Validates messages against strict healthcare compliance and regulatory standards.")
    Component("External Protocol Adapter", "External Protocol Adapter", "Apache Camel", "Adapts external protocols for secure communication with external healthcare systems.")
}

Rel("FHIR Route Orchestrator", "Data Transformation Processor", "Delegates parsing and transformation", "Java method invocation")
Rel("FHIR Route Orchestrator", "Validation & Compliance Interceptor", "Passes messages for compliance checks", "Interceptor chain")
Rel("External Protocol Adapter", "FHIR Route Orchestrator", "Forwards ingested messages", "Internal Camel routing")

@enduml

Event Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(event_broker, "Event Broker") {
    Component(Kafka Cluster Core, "Kafka Cluster Core", "Apache Kafka with KRaft consensus", "High-throughput, fault-tolerant event broker core managing asynchronous clinical message streams.")
    Component(Strimzi Operator, "Strimzi Operator", "Kubernetes Operator", "Automates the management, provisioning, and operations of the Kafka cluster.")
    Component(Schema Registry, "Schema Registry", "Confluent Schema Registry", "Enforces structural validation and schema evolution for event payloads.")
    Component(MirrorMaker 2, "MirrorMaker 2", "Apache Kafka MirrorMaker 2", "Replicates disaster recovery pipeline data across hybrid boundaries from on-prem-k8s to AWS eu-central-1.")
}

Rel(Strimzi Operator, Kafka Cluster Core, "Manages and configures")
Rel(Kafka Cluster Core, Schema Registry, "Validates message schemas against")
Rel(Kafka Cluster Core, MirrorMaker 2, "Replicates topic data to disaster recovery targets via")
@enduml
